theme.css:
/* theme: Circuit Breaker | A market panic logged in red numerals on dark silicon, the AI trade's unwind ticking down like a runaway counter. */
/* mood: bad */
/* layout: hero=poster; major-events=banner/grid-2; political-news=numbered/stack; financial-news=stat/stack; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=timeline/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/grid-2 */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #2a1215;
  --ink: #f5e8e4;
  --ink-soft: #d8c8c3;
  --muted: #b39a94;
  --accent: #ff5c5c;
  --accent-ink: #1a0000;
  --rule: #4a2a2e;
  --font-display: var(--ff-unbounded), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

.diary-page {
  background: 
    linear-gradient(135deg, transparent 0%, rgba(255, 92, 92, 0.04) 50%, transparent 100%),
    var(--paper);
}

/* Header: a red alarm wall */
.diary-page[data-hero="poster"] .diary-hero {
  background: var(--accent);
  border-bottom: 0;
  position: relative;
}

.diary-page[data-hero="poster"] .diary-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: 
    repeating-linear-gradient(
      90deg,
      transparent 0px,
      transparent 24px,
      rgba(26, 0, 0, 0.15) 24px,
      rgba(26, 0, 0, 0.15) 25px
    );
  pointer-events: none;
}

.diary-page[data-hero="poster"] .diary-hero-inner {
  position: relative;
  padding-block: 3rem 4rem;
}

.diary-page[data-hero="poster"] .diary-crumbs a {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent-ink);
  opacity: 0.85;
}

.diary-page[data-hero="poster"] .diary-crumbs a::before {
  content: "← ";
}

.diary-page[data-hero="poster"] .diary-crumbs a:hover {
  opacity: 1;
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-kicker {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent-ink);
  margin-top: 2.5rem;
}

.diary-page[data-hero="poster"] .diary-title {
  font-family: var(--font-display);
  font-size: clamp(3rem, 10vw, 7.5rem);
  font-weight: 800;
  line-height: 0.92;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--accent-ink);
  max-width: none;
}

.diary-page[data-hero="poster"] .diary-summary {
  font-family: var(--font-body);
  font-size: clamp(1.15rem, 1.8vw, 1.35rem);
  line-height: 1.6;
  color: var(--accent-ink);
  max-width: 44rem;
}

.diary-page[data-hero="poster"] .diary-theme-note {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  line-height: 1.7;
  color: var(--accent-ink);
  opacity: 0.9;
}

.diary-page[data-hero="poster"] .diary-theme-name {
  background: var(--accent-ink);
  color: var(--accent);
  border-radius: 0;
  padding: 0.15rem 0.5rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.72rem;
}

/* Contents rail: a falling ticker */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-label {
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.diary-page .diary-toc-link {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  color: var(--muted);
}

/* Section frames */
.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 3.5rem;
}

.diary-page .diary-section-head {
  position: relative;
  margin-bottom: 2rem;
  padding-bottom: 0.75rem;
  border-bottom: 2px solid var(--accent);
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-transform: uppercase;
}

/* Cards: shared dark-panel geometry */
.diary-page .diary-card {
  container-type: inline-size;
}

.diary-page .diary-card-inner {
  gap: 0.9rem;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1.22;
  letter-spacing: -0.01em;
  color: var(--ink);
}

.diary-page .diary-card-body {
  font-family: var(--font-body);
  font-size: 1.06rem;
  line-height: 1.72;
  color: var(--ink-soft);
}

.diary-page .diary-card-thread {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 0;
  padding: 0.2rem 0.6rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Banner cards: a hard red band */
.diary-page [data-card="banner"] .diary-card-inner {
  border: 1px solid var(--rule);
  background: var(--paper-alt);
  gap: 0;
}

.diary-page [data-card="banner"] .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 0.9rem 1.25rem;
  font-size: 1.1rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.diary-page [data-card="banner"] .diary-card-body {
  padding: 1.25rem;
  background: var(--paper-alt);
}

/* Numbered cards: index as a hard counter */
.diary-page [data-card="numbered"] .diary-card-inner {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 1.5rem;
  row-gap: 0.8rem;
  padding: 0;
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page [data-card="numbered"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.25rem;
  font-weight: 800;
  line-height: 0.85;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

/* Stat cards: figures burst out of the dark */
.diary-page [data-card="stat"] .diary-card-inner {
  border: 1px solid var(--rule);
  background: var(--paper-alt);
  padding: 1.75rem 1.5rem;
  position: relative;
  overflow: hidden;
}

.diary-page [data-card="stat"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 12cqi, 4rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.diary-page [data-card="stat"] .diary-card-title {
  margin-top: 0.5rem;
}

/* Outline cards: thin red frames */
.diary-page [data-card="outline"] .diary-card-inner {
  border: 1px solid var(--accent);
  background: transparent;
  padding: 1.4rem;
}

/* Timeline cards: news hanging off a falling line */
.diary-page [data-card="timeline"] .diary-card-inner {
  padding-left: 2rem;
  border-left: 2px solid var(--accent);
}

.diary-page [data-card="timeline"] .diary-card-inner::before {
  content: "";
  position: absolute;
  left: -0.45rem;
  top: 0.5rem;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

/* Tile cards: solid blocks for the outlook */
.diary-page [data-card="tile"] .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 1.75rem 1.5rem;
}

.diary-page [data-card="tile"] .diary-card-title {
  font-size: 1.2rem;
  font-weight: 700;
}

/* Plain cards: editorial flow */
.diary-page [data-card="plain"] .diary-card-inner {
  gap: 0.9rem;
}

/* Layout tweaks */
.diary-page .diary-stories--stack {
  max-width: 44rem;
  gap: 2.75rem;
}

.diary-page .diary-stories--grid-2 {
  gap: 1.75rem;
}

.diary-page .diary-stories--grid-3 {
  gap: 1.75rem;
}

.diary-page .diary-stories--masonry {
  columns: 2 18rem;
  column-gap: 1.75rem;
}

.diary-page .diary-stories--masonry > .diary-card {
  margin-bottom: 1.75rem;
}

/* Prose: red-rule underlines and list bullets */
.diary-page .diary-prose {
  font-family: var(--font-body);
  font-size: 1.08rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  font-family: var(--font-ui);
  font-size: 0.68em;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
  margin-left: 0.15em;
  overflow-wrap: anywhere;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-prose blockquote {
  border-left: 3px solid var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  font-family: var(--font-ui);
  font-size: 0.85em;
  font-weight: 600;
  color: var(--accent);
}

/* Drop cap: the day starts with a red fall */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  font-size: 3.8em;
  font-weight: 800;
  line-height: 0.8;
  color: var(--accent);
}

/* Markets: red-tinged panels with a fast pulse */
.diary-page .diary-markets-wrap {
  gap: 1.5rem;
  margin-bottom: 2.5rem;
}

.diary-page .diary-markets-label {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 0.8rem 0.9rem 0.6rem;
}

.diary-page .diary-spark-label {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  color: var(--muted);
}

.diary-page .diary-spark-value {
  font-family: var(--font-ui);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-spark-change {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--ink-soft);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-line polyline {
  stroke: var(--accent);
}

/* Footer: end on the same red note */
.diary-page .diary-footer {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
  border-top: 1px solid var(--rule);
}

.diary-page .diary-footer a {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Wide screens: sidebar rail keeps its line */
@media (min-width: 1024px) {
  .diary-page .diary-toc {
    background: none;
    border: 0;
  }

  .diary-page .diary-toc-list {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

/* Reduce motion: keep it still */
@media (prefers-reduced-motion: reduce) {
  .diary-page *,
  .diary-page *::before,
  .diary-page *::after {
    animation: none !important;
    transition: none !important;
  }
}
